#include <iostream>

using namespace std;

class Account
{
	private:
		double balance;
		string name;
	public:
		// no args constructor
		// Default constructor get generated by compiler if no other constructor specified explicitly.
		Account()
		{
			cout << "no args constructor called" << endl;
		}


		// Parameterized constructor
		Account(double balance1, string name1)
		{
			cout << "Parameterized constructor called" << endl;
			balance = balance1;
			name = name1;
		}

		~Account()
		{
			cout << " Desctructor called for " << name << endl;
		}

		// inline methods
		double get_balance(void)
		{ 
			return balance;
		}
		void set_balance(double bal) 
		{
			balance = bal;
		}

		// Non inline methods
		void set_name(string name1);
};

void Account::set_name(string name1)
{
	name = name1;
};

int main()
{
	Account acc1;

	cout << "Original Balance = " << acc1.get_balance() << endl;
	acc1.set_balance(100);
	acc1.set_name("FirstObject");
	cout << "Modified Balance = " << acc1.get_balance() << endl;

	Account acc2(200, "SecondObject");
	cout << "Original Balance = " << acc2.get_balance() << endl;
	
	return 0;
}
